<template><el-drawer v-model="visible" size="720"><template #header><div><h2>{{scenario?.name}}</h2><span class="muted">维护测试数据、脚本与录制</span></div></template><el-tabs v-model="tab"><el-tab-pane label="基本信息" name="base"><el-descriptions border :column="1"><el-descriptions-item label="说明">{{scenario?.description}}</el-descriptions-item><el-descriptions-item label="脚本入口"><el-text tag="code">{{scenario?.scriptEntry||'尚未绑定'}}</el-text></el-descriptions-item><el-descriptions-item label="负责人">{{scenario?.owner||'-'}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane label="测试数据" name="data"><div class="drawer-actions"><el-button type="primary" @click="generate">生成样例</el-button><el-button @click="generate(true)">AI 生成</el-button><el-button>上传 Excel / CSV</el-button></div><el-table :data="datasets" border><el-table-column prop="name" label="名称"/><el-table-column prop="rowCount" label="行数" width="80"/><el-table-column prop="createdAt" label="创建时间"/></el-table></el-tab-pane><el-tab-pane label="脚本与录制" name="record"><el-alert title="推荐使用录制快速创建脚本，再由维护人员补充断言。" type="info" show-icon/><el-form label-position="top"><el-form-item label="录制环境"><el-select v-model="environment"><el-option v-for="env in store.environments" :key="env.key" :label="env.name" :value="env.key"/></el-select></el-form-item></el-form><el-button type="primary" :icon="VideoCamera" @click="startRecord">开始录制</el-button><div v-if="recording" class="record-command"><strong>本地录制命令</strong><el-input :model-value="recording.localCommand" readonly><template #append><el-button @click="copy">复制</el-button></template></el-input><p>完成浏览器操作后，回到这里刷新录制状态并绑定脚本。</p><el-button @click="refresh">刷新录制状态</el-button></div></el-tab-pane></el-tabs></el-drawer></template>
<script setup>import{ref}from'vue';import{VideoCamera}from'@element-plus/icons-vue';import{ElMessage}from'element-plus';import{api}from'../api';import{usePlatformStore}from'../stores/platform';const emit=defineEmits(['changed']),store=usePlatformStore(),visible=ref(false),scenario=ref(),tab=ref('base'),datasets=ref([]),recording=ref(),environment=ref('test');async function open(item){scenario.value=item;datasets.value=await api(`/api/scenarios/${item.key}/datasets`);environment.value=store.environments.find(e=>e.isDefault)?.key||'test';visible.value=true}async function generate(useLlm=false){const result=await api(`/api/scenarios/${scenario.value.key}/sample-data`,{method:'POST',body:JSON.stringify({count:3,useLlm})});ElMessage.success(`已生成 ${result.rows?.length||0} 行样例数据`)}async function startRecord(){recording.value=await api('/api/recordings/start',{method:'POST',body:JSON.stringify({scenarioKey:scenario.value.key,environmentKey:environment.value})})}async function copy(){await navigator.clipboard.writeText(recording.value.localCommand);ElMessage.success('命令已复制')}async function refresh(){recording.value=await api(`/api/recordings/${recording.value.id}`)}defineExpose({open})</script>
